const items = $input.all();
const results = [];

for (const item of items) {
  const data = item.json;
  // 兼容两种来源：
  // 1. Shopify Webhook: data.body = { message, customerName, ... }
  // 2. Gmail (Extract Email Data): data.body = { message, ... }, data.gmail_thread_id
  const body = data.body || data;
  const message = body.message || '';
  const ticketId = body.ticketId || data.ticketId || Date.now();
  const customerName = body.customerName || data.customerName || 'Customer';
  const customerEmail = body.customerEmail || data.customerEmail || '';
  const platform = body.platform || data.platform || 'shopify';
  const orderId = (body.orderId !== undefined ? body.orderId : data.orderId) || null;
  const gmail_thread_id = data.gmail_thread_id || null;
  const gmail_message_id = data.gmail_message_id || null;

  if (!message || message.trim().length === 0) {
    continue;
  }

  const startTime = Date.now();
  const forceError = String(ticketId).startsWith('test-force-error-');

  results.push({
    json: {
      startTime,
      ticketId,
      customerName,
      customerEmail,
      platform,
      orderId,
      gmail_thread_id,
      gmail_message_id,
      chatInput: 'Platform: ' + platform + '\nMessage: ' + message + '\nOrder ID: ' + (orderId || 'None'),
      forceError
    }
  });
}

return results;

const results = [];
const allInputs = $input.all();
const allTickets = $('Parse Input').all();

for (let i = 0; i < allInputs.length; i++) {
  const agentOutput = allInputs[i].json.output || allInputs[i].json.text || '{}';
  const ticket = (allTickets[i] || allTickets[0]).json;

  let parsed;
  try {
    const cleaned = agentOutput
      .replace(/^```json\s*/i, '')
      .replace(/^```\s*/i, '')
      .replace(/```\s*$/i, '')
      .trim();
    const match = cleaned.match(/\{[\s\S]*\}/);
    const jsonStr = match ? match[0] : cleaned;
    try {
      parsed = JSON.parse(jsonStr);
    } catch {
      const fixed = jsonStr.replace(/"((?:[^"\\]|\\.)*)"/g, (m, inner) => {
        return '"' + inner.replace(/\n/g, '\\n').replace(/\r/g, '\\r').replace(/\t/g, '\\t') + '"';
      });
      parsed = JSON.parse(fixed);
    }
  } catch (parseError) {
    const classMatch = agentOutput.match(/"classification"\s*:\s*"(auto|draft|escalate)"/i);
    const replyMatch = agentOutput.match(/"reply"\s*:\s*"((?:[^"\\]|\\.)*)"/);
    const reasonMatch = agentOutput.match(/"reason"\s*:\s*"((?:[^"\\]|\\.)*)"/);
    const riskMatch = agentOutput.match(/"risk_level"\s*:\s*"(low|medium|high)"/i);
    if (classMatch) {
      parsed = {
        classification: classMatch[1],
        reason: reasonMatch ? reasonMatch[1] : 'Extracted from malformed JSON',
        risk_level: riskMatch ? riskMatch[1] : 'medium',
        reply: replyMatch ? replyMatch[1] : null
      };
    } else {
      parsed = { classification: 'escalate', reason: 'AI output parse error', risk_level: 'high', reply: null };
    }
  }

  const classification = ['auto', 'draft', 'escalate'].includes(parsed.classification)
    ? parsed.classification
    : 'escalate';
  if (classification === 'escalate' && parsed.classification !== 'escalate') {
    parsed.reason = 'Invalid classification: ' + parsed.classification;
  }

  let status;
  if (classification === 'auto') status = 'auto_replied';
  else if (classification === 'draft') status = 'needs_review';
  else status = 'escalated';

  const aiCallTimeMs = Date.now() - ticket.startTime;

  results.push({
    json: {
      aiCallTimeMs,
      status,
      classification,
      reason: parsed.reason || '',
      riskLevel: parsed.risk_level || 'high',
      reply: parsed.reply || null,
      ticketId: ticket.ticketId,
      customerName: ticket.customerName,
      customerEmail: ticket.customerEmail,
      platform: ticket.platform,
      originalMessage: ticket.chatInput,
      gmail_thread_id: ticket.gmail_thread_id || null,
      gmail_message_id: ticket.gmail_message_id || null
    }
  });
}

return results;

const results = [];
