for (let i = 0; i < allInputs.length; i++) {
  const error = allInputs[i].json.error || {};
  const ticket = (allTickets[i] || allTickets[0]).json;

  const executionId = $execution.id;
  const workflowId = $workflow.id;
  const workflowName = $workflow.name;
  const failedNode = error.node?.name || 'AI Agent';
  const aiCallTimeMs = Date.now() - ticket.startTime;

  results.push({
    json: {
      aiCallTimeMs,
      status: 'needs_review',
      classification: 'draft',
      reason: 'AI 分类服务暂时不可用，已标记为待审核: ' + (error.message || 'Unknown error'),
      riskLevel: 'medium',
      reply: '感谢您的消息。我们的团队会尽快为您处理。',
      ticketId: ticket.ticketId,
      customerName: ticket.customerName,
      customerEmail: ticket.customerEmail,
      platform: ticket.platform,
      originalMessage: ticket.chatInput,
      gmail_thread_id: ticket.gmail_thread_id || null,
      gmail_message_id: ticket.gmail_message_id || null,
      errorDetails: JSON.stringify(error),
      fallbackApplied: true,
      n8nExecutionId: executionId,
      n8nWorkflowId: workflowId,
      n8nWorkflowName: workflowName,
      failedNode: failedNode
    }
  });
}

return results;

