return [{
  json: {
    'Ticket ID': String($json.ticketId),
    'Customer Email': $json.customerEmail,
    'Customer Name': $json.customerName,
    'Platform': $json.platform,
    'Classification': $json.classification,
    'Status': $json.status,
    'Risk Level': $json.riskLevel,
    'Escalation Reason': $json.reason || '',
    'AI Reply': $json.reply || '',
    'Original Message': $json.originalMessage || '',
    'Timestamp': new Date().toISOString()
  }
}];

const items = $input.all();
const results = [];

for (const item of items) {
  const email = item.json;

  // email.from 是对象：{ value: [{ address, name }], text }
  let customerEmail = '';
  let customerName = 'Customer';

  if (email.from && email.from.value && email.from.value.length > 0) {
    customerEmail = email.from.value[0].address || '';
    customerName = email.from.value[0].name || email.from.value[0].address || 'Customer';
  } else if (typeof email.from === 'string') {
    const match = email.from.match(/<([^>]+)>/);
    customerEmail = match ? match[1].trim() : email.from.trim();
    customerName = email.from.replace(/<[^>]+>/, '').trim() || 'Customer';
  }

  const message = email.snippet || email.bodyText || email.text || 'No content';
  const body = { message, customerName, customerEmail, platform: 'gmail', ticketId: Date.now(), orderId: null };

  results.push({
    json: {
      body,
      gmail_thread_id: email.threadId || null,
      gmail_message_id: email.id || null
    }
  });
}

return results;

