const results = [];
const allInputs = $input.all();

for (const item of allInputs) {
  const ticket = item.json;
  const content = `Support Ticket #${ticket.ticketId}\n\nClassification: ${ticket.classification}\nRisk Level: ${ticket.riskLevel}\nStatus: ${ticket.status}\n\nCustomer: ${ticket.customerName} (${ticket.customerEmail})\n\nOriginal Message:\n${ticket.originalMessage}\n\nAI Classification Reason:\n${ticket.reason}\n\nAI Generated Reply:\n${ticket.reply || 'Needs manual handling'}\n\nTimestamp: ${new Date().toISOString()}\n`;
  const binaryData = Buffer.from(content, 'utf-8').toString('base64');
  results.push({
    json: ticket,
    binary: {
      data: {
        data: binaryData,
        mimeType: 'text/plain',
        fileName: `Ticket-${ticket.ticketId}.txt`
      }
    }
  });
}

return results;

const results = [];
const allInputs = $input.all();

for (const item of allInputs) {
  const ticket = item.json;
  const message = ticket.originalMessage || '';
  const hasSchedulingKeywords = /schedule|appointment|meeting|book|call|demo|visit/i.test(message);
  if (!hasSchedulingKeywords) {
    continue;
  }
  const tomorrow = new Date();
  tomorrow.setDate(tomorrow.getDate() + 1);
  tomorrow.setHours(10, 0, 0, 0);
  const endTime = new Date(tomorrow);
  endTime.setHours(11, 0, 0, 0);
  results.push({
    json: {
      ...ticket,
      calendar_start: tomorrow.toISOString(),
      calendar_end: endTime.toISOString()
    }
  });
}

return results;
